using System; using System.IO; namespace Common.Infrastructure.Logging { public class AuditLogger { private readonly string _logFilePath; public AuditLogger() { var logDir = Path.Combine(Directory.GetCurrentDirectory(), "Logs"); if (!Directory.Exists(logDir)) Directory.CreateDirectory(logDir); _logFilePath = Path.Combine(logDir, "audit.log"); } public void Log(string userName, string userId, string role, string action, string entity, string details) { string logEntry = $@" [{DateTime.Now:yyyy-MM-dd HH:mm:ss}] User: {userName} (ID: {userId}, Role: {role}) Action: {action} Entity: {entity} Details: {details} ----------------------------------------------------------"; File.AppendAllText(_logFilePath, logEntry + Environment.NewLine); } } }